import ReactDOM from 'react-dom';
import React from 'react';


//Components
import Scrollable from './components/Scrollable';

//React Hooks
import { useEffect, useState, useRef } from 'react';
import { color, delay, motion } from 'framer-motion';

// Font Awesome Imports
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faArrowRight, faCaretRight, faCaretLeft } from '@fortawesome/free-solid-svg-icons';

import { InfiniteMovingCards } from "../src/components/ui/infinite-moving-cards";
import './App.css';

//Images
import Cass from './images/GreyScale.png'
import BloomOne from './images/bloom_in_harmony/bloom-1.png'
import BloomTwo from './images/bloom_in_harmony/bloom-2.png'

import indigoImageOne from './images/indigo_avenue/indigo-1.png'
import indigoImageTwo from './images/indigo_avenue/indigo-2.png'
import indigoImageThree from './images/indigo_avenue/indigo-3.png'


import roundHouseImageOne from './images/round_house/roundhouse-1.png'
import roundHouseImageTwo from './images/round_house/roundhouse-2.png'




import logo from './images/logo.png'
import butterfly from './images/butterfly-svgrepo-com.svg';


import useMediaQuery from './components/hooks/useMediaQuery';
import { coolGray } from 'tailwindcss/colors';


function App() {


  const data = [


    {
      
      name: "Bloom In Harmony",
      image: [BloomOne, BloomTwo],
    },
    {
      
      name: "Indigo Avenue",
      image: [indigoImageOne, indigoImageTwo, indigoImageThree ],
    },
    {
      
      name: "Eddie Beats",
      image: [BloomTwo, BloomOne, BloomTwo],
    },
    {
      
      name: "3B Real Estate",
      image: [BloomTwo, BloomOne],
    },
    {
      
      name: "Round House",
      image: [roundHouseImageOne, roundHouseImageTwo],
    },
   
 
  ]

  const [loadElements, setLoadElements] = useState(false);
  const [moveElement, setMoveElement] = useState(false);
  const [showProject, setShowProject] = useState(false);
  const [nameTransition, setNameTransition] = useState(true);


  const [index, setIndex] = useState(0);


  const nextItem = () => {
    setNameTransition(false);
    setTimeout(() => {

      setIndex((prevIndex) => (prevIndex + 1) % data.length)
      setNameTransition(true);

    }, 500)
  }

  const prevItem = () => {

    setNameTransition(false);
    setTimeout(() => {


      setIndex((prevIndex) => (prevIndex - 1 +  data.length) % data.length)
      setNameTransition(true);

    }, 500)
  }

  // const handleShow = () => {
    
    
  //   setShowProject(!showProject);
  //   console.log('Menu open');
  // }

  //This defines the intersection observer
 
  const [inView, setInView] = useState([]);
  const [socialView, setSocialView] = useState(false);
  
  const observerRefs = useRef([]); // Array of refs to track multiple elements
  const observerRef = useRef(null)
  const isDesktop = useMediaQuery('(min-width: 460px)');

  useEffect(() => {
    // Intersection Observer callback function
    const handleIntersection = (entries) => {
      const [entry] = entries;
      // Set state to true when element is in view
      setSocialView(entry.isIntersecting);
    };
    
    // Create a new IntersectionObserver instance
    const observer = new IntersectionObserver(handleIntersection, {
      threshold: 0.1, // 50% of the element needs to be visible
    });

    // Observe the div element
    if (observerRef.current) {
      observer.observe(observerRef.current);
    }

    // Cleanup observer on component unmount
    return () => {
      if (observerRef.current) {
        observer.unobserve(observerRef.current);
      }
    };
  }, []);




    useEffect(() => {
      setInView(new Array(3).fill(false)); // Adjust the number of containers here

      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry, index) => {
            if (entry.isIntersecting) {
              setInView((prev) => {
                const updatedInView = [...prev];
                updatedInView[index] = true; // Mark this specific element as visible
                return updatedInView;
              });
            }
          });
        },
        { threshold: 0.5 } // Trigger when 50% of the element is in view
      );

      observerRefs.current.forEach((ref) => {
        if (ref) observer.observe(ref)
      });

      return () => {
        // Cleanup observer on unmount
        observer.disconnect();
      };
    }, []);
  

  useEffect(() => {


  })


  //This useEffect controls the other elements on screen outside of the Hero Section
  useEffect(() => {

    //Sets timer to be 3 seconds before showing other elements
    const timer = setTimeout(() => {
      setLoadElements(true);
    }, 1500); //Wait for 3 seconds
  })
  useEffect(() => {
    const timer = setTimeout(() => {
      setMoveElement(true); // Update state to trigger animation
    }, 1500)
  })



  const testimonials = [
    {

    position: 'Developer',
    review: 'We were very impressed by Cassies attention to detail and how she was able to bring our ideas to life!',
    icon: 'Hunter Mann'
  },
  {

    position: 'President',
    review: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nulla sit amet eros ipsum. Fusce congue laoreet libero, in molestie est aliqu',
    icon: 'Round House'
  },
 


]

 

  return (
    

        <div className='grid md:grid-areas-layout md:grid-rows-layout h-full w-full md:w-[80%] grid-cols-1 md:grid-cols-3 gap-3 p-2 md:p-0 m-auto md:mt-9'>


            {/* Header */}
            <motion.div initial={{ opacity: 0, x: -100 }} animate={{ opacity: loadElements? 1: 0, x: loadElements? 0 : -100}} transition={{ duration: 0.2 }} className='md:grid-in-header md:row-span-1 flex items-center font-mono justify-center relative rounded-xl bg-lime-50'>
              <motion.img src={logo} initial={{opacity: 0}} animate={{opacity: 1}} transition={{delay: 2}} className='w-[8rem]' />
            </motion.div>


            {/* Creativity */}
            <motion.div initial={{ opacity: 0, x1: -300 }} animate={{ opacity: loadElements? 1: 0}} transition={{ duration: 0.2 }} className='col-span-1 md:grid-in-create md:row-span-2 row-span-10 p-[3rem] flex flex-col border-2 items-start relative justify-start rounded-xl bg-lime-50'>
              
              <motion.img initial={{rotate: 0}} animate={{rotate: 360}} transition={{duration:0.5, delay: 1.5}} src={butterfly} alt="" className='w-[10rem] absolute right-0 md:right-[6rem] md:top-[4rem] top-4' />

              <motion.div initial={{ y:300 }} animate={{ y: 0 }} transition={{ duration:1, delay:1}} className=' w-[10rem] mt-7 md:mt-20'>

                <motion.span className='font-play font-bold md:text-6xl md:font-semibold text-4xl'>Creativity is the greatest rebellion in existence.</motion.span>


              </motion.div>
              
            </motion.div>

            {/* Gold Picture container */}
            <motion.div animate={{y: [ isDesktop? -100 : -400, isDesktop? -200 : -400, 0], scale:[0.8, 0.6, 1]}} transition={{ duration: 0.6, delay:1}} className='col-span-1 md:grid-in-hero row-span-2 rounded-xl bg-gradient-to-r from-yellow-500 to-yellow-700'>
              <img className='rounded-xl h-full w-full' src={Cass} alt="Hero" />
            </motion.div>

            {/* Bio Section */}

            {[...Array(1)].map((_, index) => (


                <motion.div key={index} ref={(el) => (observerRefs.current[index] = el)} initial={{ opacity: 0 }} animate={{ opacity: inView[index]? 1 : 0 }} transition={{ duration: 1 }}  className='md:grid-in-bio col-span-1 row-span-3 rounded-xl bg-lime-50 p-[3rem] font-merri flex flex-col justify-center items-center'>
                <h1 className='text-3xl mb-5 md:mb-5 font-play font-bold'>Graphic Designer</h1>
                Cassie is a detail-oriented graphic designer with extensive experience in marketing and advertising. A University of Tennessee graduate with a degree in Communications, she specializes in Advertising and Business Administration. Cassie is skilled in creating and managing campaigns for brand awareness, rebranding, and outreach, using both digital tools like Adobe Creative Suite and traditional media, along with social and email marketing strategies.           
                </motion.div>

           
              ))}

            {/* Projects */}
            <motion.div initial={{ opacity: 0 }} animate={{opacity: loadElements? 1 : 0 }} className='col-span-1 md:grid-in-work row-span-6 rounded-xl bg-lime-50 p-[3rem]'>
              
              <div className='font-play relative' id='project-container'>
                <h2 className='mb-[3rem] text-3xl font-bold'>work</h2>
                <ul id='project' className=''>

               

                        <li className='border-b mb-1 mt-2 p-4 cursor-pointer'>
                        <div className='flex items-center justify-between'>

                          <div onClick={prevItem} className='w-5 flex items-center flex-col'>
                          <FontAwesomeIcon  icon={faCaretLeft} />

                          </div>
                        <span className={`transition-all text-xl duration-500 ${nameTransition ? 'opacity-100' : 'opacity-0'}`}>{data[index].name}</span>
                        <div onClick={prevItem} className='w-5 flex items-center flex-col'>
                          <FontAwesomeIcon  icon={faCaretRight} />

                          </div>
                        </div>

                        {index === 0 && (

                        <div className= 'transition-all duration-300 opacity-100'>

                                <Scrollable items={data[index].image}  />

                          </div>

                        )}
                        {index === 1 && (

                            <div className= 'transition-all duration-300 opacity-100 '>

                            <Scrollable items={data[index].image}  />

                            </div>

                        )}
                        {index === 2 && (

                            <div className= 'transition-all duration-300 opacity-100'>

                            <Scrollable items={data[index].image}  />

                            </div>

                        )}
                          {index === 3 && (

                            <div className= 'transition-all duration-300 opacity-100'>

                            <Scrollable items={data[index].image}  />

                            </div>

                        )}
                          {index === 4 && (

                            <div className= 'transition-all duration-300 opacity-100'>

                            <Scrollable items={data[index].image}  />

                            </div>

                        )}
                              
                            



                            </li>


                  
                 
                 
                </ul>
              </div>
            </motion.div>

            {/* Contact Seciton */}
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: loadElements? 1 : 0}} className='col-span-1 md:grid-in-contact row-span-3 rounded-xl text-lime-50 bg-lime-950 p-[1rem] flex flex-col justify-end'>
              <div className='flex justify-between p-3'>
                <span className='text-sm font-merri  w-[5rem]'>Have some questions?</span>
                <FontAwesomeIcon icon={faArrowRight} />
              </div>
              <span className='mt-[10rem] font-play text-4xl'>Contact me.</span>
            </motion.div>

          {/* Reviews  */}

            <motion.div initial={{ opacity: 0 }} animate={{ opacity: loadElements? 1 : 0}} className='col-span-1 md:grid-in-reviews row-span-3 rounded-xl text-lime-50 bg-black p-[1rem] flex flex-col justify-end'>
              <div className='flex justify-between p-3'>
                <h2 className='text-md font-merri  w-[5rem]'>Testimonials</h2>
              </div>
              <div className="h-[15rem] rounded-md flex flex-col antialiased bg-black dark:bg-black dark:bg-grid-white/[0.05] items-center justify-center relative overflow-hidden">
                <InfiniteMovingCards
                  items={testimonials}
                  direction="right"
                  speed="slow"
                />
              </div>
            
            </motion.div>


            {/* Social Media */}   
            <motion.div ref={observerRef} initial={{ opacity: 0 }} animate={{ opacity: socialView ? 1 : 0 }}  transition={{ duration: 0.5 }} className='md:grid-in-social col-span-1 row-span-2 rounded-xl bg-lime-50 p-[2rem]'>
              <ul className='flex font-play text-sm font-semibold gap-2 items-center justify-center'>
                <li>Instagram</li>
                <li>Linkedin</li>
              </ul>
            </motion.div>

         

        </div>
         
    
  );
}

export default App;
